sys_script_include.script:
var Cisco_Secure_Access_Poll_Private_Resources = Class.create();
Cisco_Secure_Access_Poll_Private_Resources.prototype = {
	initialize: function () {
	},

	run: function () {
		gs.info("[CSA - PR] STEP 1: Starting PollCiscoSSEAPIPrivateResourcesuserapp.run()");
		try {
			// STEP 1: Get Bearer token
			gs.info("[CSA - PR] STEP 2: Fetching Bearer token...");
			var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
			// var token = "";
			gs.info("[CSA - PR] STEP 2: Bearer token fetched: " + (token ? "SUCCESS" : "FAILED"));

			// STEP 2: Call Cisco CSA API (Get Private Resources)
			gs.info("[CSA - PR] STEP 3: Executing REST Message 'Cisco SSE - Get Private Resource', Method 'Default GET'...");
			var r = new sn_ws.RESTMessageV2('Cisco Secure Access Private Resources', 'GET Private Resources');
			r.setRequestHeader("Authorization", "Bearer " + token);
			r.setRequestHeader("Accept", "application/json");
			var response = r.execute();
			var status = response.getStatusCode();
			gs.info("[CSA - PR] STEP 3: REST response status: " + status);

			var responseBody = response.getBody();
			gs.info("[CSA - PR] STEP 3: Raw Response: " + responseBody);

			if (status !== 200) {
				gs.error("[CSA - PR] ERROR: REST call failed with status " + status);
				// throw new Error("REST call failed with status " + status);
			}

			// STEP 4: Parse response
			gs.info("[CSA - PR] STEP 4: Parsing response...");
			var parsed = JSON.parse(responseBody);
			var csaResources = parsed.items || [];
			gs.info("[CSA - PR] STEP 4: Total private resources fetched from CSA: " + csaResources.length);

			// STEP 5: Build CMDB resource list
			gs.info("[CSA - PR] STEP 5: Querying CMDB table...");
			var cmdbGR = new GlideRecord('u_cmdb_ci_application');
			cmdbGR.query();

			var cmdbResources = {};
			var cmdbCount = 0;
			while (cmdbGR.next()) {
				var resourceId = cmdbGR.getValue('u_resource_id') || cmdbGR.getValue('name');
				cmdbResources[resourceId] = true;
				cmdbCount++;
			}
			gs.info("[CSA - PR] STEP 5: Total resources in CMDB: " + cmdbCount);

			// STEP 6: Insert new resources into the new local table
			gs.info("[CSA - PR] STEP 6: Inserting new resources into Cisco CSA Private Resources table...");
			var inserted = [];

			for (var i = 0; i < csaResources.length; i++) {
				var res = csaResources[i];
				var resourceId = res.resourceId;

				// --- Check if resource already exists in CMDB or local table ---
				var exists = cmdbResources[resourceId];

				if (!exists) {
					var localGR = new GlideRecord('u_cisco_secure_access_private_resources');
					localGR.addQuery('u_resource_id', resourceId);
					localGR.query();

					if (localGR.hasNext()) {
						gs.info("[CSA - PR] STEP 6: Resource already exists in local table: " + resourceId);
						exists = true;
					}
				}

				// --- Insert only if not exists anywhere ---
				if (!exists) {
					var gr = new GlideRecord('u_cisco_secure_access_private_resources');
					gr.initialize();

					// --- Default flags ---
					gr.u_status = "pending";
					gr.u_send_alert = "no";

					// --- Map CSA fields to correct ServiceNow columns ---
					gr.u_created_at = res.createdAt;
					gr.u_modified_at = res.modifiedAt;
					gr.u_dns_server_id = res.dnsServerId;
					gr.u_created_by = res.createdBy;
					gr.u_resource_group_ids = Array.isArray(res.resourceGroupIds) ? res.resourceGroupIds.join(',') : "";
					gr.u_resource_id = res.resourceId;
					gr.u_description = res.description;
					gr.u_name = res.name;
					gr.u_access_types = Array.isArray(res.accessTypes) ? JSON.stringify(res.accessTypes) : "";
					gr.u_import_source = res.importSource;
					gr.u_enforcement = res.enforcement;
					gr.u_logo_url = res.logoUrl;
					gr.u_reachable_addresses = Array.isArray(res.accessTypes)
						? [].concat.apply([], res.accessTypes.map(function (type) {
							return type.reachableAddresses || [];
						})).join(',')
						: "";
					gr.u_certificate_id = res.certificateId;
					gr.u_modified_by = res.modifiedBy;
					gr.u_protocol_ports = Array.isArray(res.resourceAddresses)
						? JSON.stringify([].concat.apply([], res.resourceAddresses.map(function (addr) {
							return addr.protocolPorts || [];
						})))
						: "";
					gr.u_resource_addresses = Array.isArray(res.resourceAddresses) ? JSON.stringify(res.resourceAddresses) : "";

					var sysId = gr.insert();
					gs.info("[CSA - PR] STEP 6: Inserted resource: " + (res.name || res.resourceId) + " (sys_id: " + sysId + ")");
					inserted.push(res.name || res.resourceId);
				} else {
					gs.info("[CSA - PR] STEP 6: Resource skipped (already exists): " + resourceId);
				}
			}

			if (inserted.length > 0) {
				gs.info("[CSA - PR] STEP 7: Inserted new Cisco CSA Private Resources: " + inserted.join(", "));
			} else {
				gs.info("[CSA - PR] STEP 7: No new private resources to insert.");
			}

			gs.info("[CSA - PR] STEP 8: PollCiscoSSEAPIPrivateResourcesuserapp.run() completed.");

		} catch (ex) {
			gs.error('[CSA - PR] ERROR: Failed to import Cisco CSA Private Resources: ' + ex.message);
		}
	},

	type: 'Cisco_Secure_Access_Poll_Private_Resources'
};
